const resolvers = {
  Post: {
    // parent = the Post object, args = field args, ctx = per-request, info = query AST
    author: (parent, args, ctx, info) => ctx.loaders.user.load(parent.authorId),
  },
}

type Post {
  id: ID!            # always present
  tags: [String!]!   # list non-null AND items non-null
  images: [String]   # both nullable — one bad item cannot empty the list
  author: User       # nullable on purpose: fetched from another service
}

fragment PostCard on Post { id title author { name } }

query Feed {
  feed { ...PostCard }
  search(term: "graphql") {
    ... on Post { ...PostCard }   # inline fragment: only for the matching type
  }
}

// created per request — a module-scope loader leaks data between users
const userLoader = new DataLoader((ids) => usersByIds(ids))
// usersByIds MUST return rows in the same order as ids, nulls for misses

const resolvers = { Post: { author: (p, _a, ctx) => ctx.userLoader.load(p.authorId) } }

// the store is flat, keyed by __typename + id
{
  "Post:42": { id: "42", title: "Hello", author: { __ref: "User:7" } },
  "User:7":  { id: "7", name: "An" }   // updating this reflects on every screen
}

query { posts(first: 20, after: "Y3Vyc29yOjIw") {
  edges { cursor node { id title } }
  pageInfo { hasNextPage endCursor }
} }

// authorize per field, not per route — one query can touch many types
const resolvers = {
  Post: {
    revenue: (post, _a, ctx) => (ctx.can('read:revenue', post) ? post.revenue : null),
  },
}

input UpdatePostInput { id: ID!, title: String }

type UpdatePostPayload {
  post: Post                 # enough for the client to update its cache
  errors: [UserError!]!      # business errors modelled as data, not thrown
}

type Mutation { updatePost(input: UpdatePostInput!): UpdatePostPayload! }

type User {
  firstName: String!
  fullName: String! @deprecated(reason: "Use firstName/lastName. Removed 2026-12-01")
}

interface Node { id: ID! }          # shared fields — queryable directly
union SearchResult = Post | User   # nothing in common — needs inline fragments

query { search(term: "a") { ... on Post { title } ... on User { name } } }

query Feed($withAuthor: Boolean!, $skipBody: Boolean!) {
  feed {
    title
    body   @skip(if: $skipBody)
    author @include(if: $withAuthor) { name }
  }
}
